      expect(gumballPlaneScaleFactors([1, 2], [2, 4])).toEqual([2, 2]);
      expect(gumballPlaneScaleFactors([3, 4], [6, 8], true)).toEqual([2, 2]);
      expect(gumballPlaneScaleFactors([1, 0], [2, 0], true)).toEqual([2, 2]);
      const gumballMesh = new THREE.Mesh();
